14	/**
15	 * Component for rendering a link to a player's profile with various formatting options.
16	 *
17	 * @param player - The player data to link to
18	 * @param year - The year to include in the link URL (optional)
19	 * @param format - The format for the link label (default: 'name')
20	 *   - 'name': Displays the player's name as the link label
21	 *   - 'left-arrow': Displays a left arrow icon, indicating a link to the previous player
22	 *   - 'right-arrow': Displays a right arrow icon, indicating a link to the next player
23	 * @param wrap - Whether the player's name may wrap onto multiple lines (default: false,
24	 *   i.e. the link gets enough min-width to keep a typical name on one line)
25	 * @returns A React element representing the formatted player link
26	 * @example
27	 * <PlayerLink player={player} year={2024} format="name" />
28	 * // Renders a link with the player's name as the label, linking to "/footy/player/{player.id}/2024"
29	 * @example
30	 * <PlayerLink player={player} format="left-arrow" />
31	 * // Renders a link with a left arrow icon, linking to "/footy/player/{player.id}"
32	 * @example
33	 * <PlayerLink player={player} format="right-arrow" />
34	 * // Renders a link with a right arrow icon, linking to "/footy/player/{player.id}"
35	 */
36	export interface Props {
37	    player: PlayerType;
38	    year: number;
39	    format?: 'name' | 'left-arrow' | 'right-arrow';
40	    wrap?: boolean;
41	    goalie?: boolean | null | undefined;
42	}
43	
44	export const PlayerLink = ({
45	    player,
46	    year,
47	    format = 'name',
48	    wrap = false,
49	    goalie = false,
50	}: Props) => {
51	    const theme = useMantineTheme();
52	    let ariaLabel: string | undefined;
53	    let miw: CSSProperties['minWidth'];
54	
55	    switch (format) {
56	        case 'name':
57	            ariaLabel = `${player.name ?? 'Unknown'}`;
58	            miw = wrap ?
59	                theme.other.playerNameMinWidthMultiLine :
60	                theme.other.playerNameMinWidthSingleLine;
61	            break;
62	        case 'left-arrow':
63	            ariaLabel = `Previous player: ${player.name ?? 'Unknown'}`;
64	            break;
65	        case 'right-arrow':
66	            ariaLabel = `Next player: ${player.name ?? 'Unknown'}`;
67	            break;
68	    }
69	
70	    const link = (
71	        <Anchor
72	            href={`/footy/player/${player.id}${year ? `/${year}` : ''}`}
73	            aria-label={ariaLabel}
74	            miw={miw}
75	        >
76	            {(() => {
77	                switch (format) {
78	                    case 'name':
79	                        return player.name;
80	                    case 'left-arrow':
81	                        return <IconArrowBigLeftLine aria-hidden />;
82	                    case 'right-arrow':
83	                        return <IconArrowBigRightLine aria-hidden />;
84	                }
85	            })()}
86	            {goalie ? <GoalieIndicator /> : null}
87	        </Anchor>
88	    );
89	
90	    if (format === 'name') {
91	        return link;
92	    }
93	    else {
94	        return (
95	            <Tooltip label={player.name} withArrow>
96	                {link}
97	            </Tooltip>
98	        );
99	    }
100	};
